        "gameUse": "20-13으로 이긴 경기에서 Rams의 13 personnel 사용 비중은 54.8%였다. 이 구성은 플레이당 5.3야드·성공률 57.5%, 다른 구성 33개 플레이는 4.4야드·27.3%였다. 수치는 NFL Next Gen Stats 집계이며 임의로 만든 효율 지표가 아니다.",
        "whyItWorks": "개념적으로는 타이트엔드가 블록과 패스의 두 역할을 할 수 있어 수비가 인원만 보고 공격을 단정하기 어렵다. 다만 이 경기의 수치는 무작위 비교가 아니다. 다운·필요 거리·경기 상황이 서로 다르므로 TE를 셋 넣은 것만으로 효율이 올랐다는 인과 증명은 아니다.",
        "defenseCounter": "수비의 관전 기준은 인원 대응과 패스 커버 인계다. 무거운 인원만 보고 앞으로 쏠리기보다 TE가 블록하는지 릴리스하는지 읽고, 라인배커와 세이프티가 담당을 넘기는 과정을 보자. 아래는 일반 개념도이며 특정 Rams 스냅의 실제 정렬 재현은 아니다.",
        "diagram": {
          "kind": "heavy-personnel-protection-release",
          "caption": "13 personnel의 인원과 TE의 보호·릴리스 선택을 설명하는 일반 개념도. 실제 스냅 재현은 아니다."
        },
        "breakdown": [
          {
            "label": "① 먼저 인원과 위치",
            "text": "RB 하나·TE 셋이라는 인원 수와 실제 서 있는 위치는 구분하자. 같은 13 personnel도 TE를 라인 옆이나 뒤로 배치할 수 있다. 수비도 누구를 박스에 넣고 누구를 커버에 남길지 선택한다."
          },
          {
            "label": "② 블록인가 패스인가",
            "text": "스냅 뒤 TE가 보호에 남는지 패스 루트로 나가는지를 먼저 보자. 개념도의 파란 블록과 노란 릴리스는 대안이며 같은 선수가 동시에 수행한 실제 동작이 아니다."
          },
          {
            "label": "③ 이 경기의 수치와 한계",
            "text": "Rams가 40개 플레이에서 13 personnel을 사용했다는 사실과 57.5% 성공률은 사례의 규모를 보여준다. 수비가 대응하는 조건도 다르므로 다른 구성의 27.3%와 단순 비교해 보편적인 우열을 정하지 말자."
          }
        ],
