            "meaning": "다음 공격권을 중시했다는 것은 감독과 쿼터백의 설명이다. 실제 선택의 우열은 성공 확률과 남은 타임아웃까지 비교해야 하며, 이 경기의 승리만으로 최적의 결정이었다고 단정할 수 없다."
