        "gameUse": "Eagles 공식 리캡의 1쿼터 11분 19초, Dallas 34야드의 1다운 10야드 장면이다. McKee가 왼쪽으로 가로지르는 Lemon에게 연결해 21야드를 전진, Dallas 13야드에 도달했다. 기사 기반 설명이며 영상 프레임을 직접 분석한 것은 아니다.",
